//! Relative date expressions like `dateparser.parse(value, locales=…, settings={"PARSERS": ["relative-time"]})`
//! (W8). Re-implementation of the dateparser flow with its own language data (`relative_dp_data.rs`, generated by
//! `tools/gen_relative_dateparser.py` from dateparser 1.4.3, the version from upstream/uv.lock):
//!
//! 1. `date.sanitize_date`
//! 2. per language (`DateDataParser._get_applicable_locales`, order like dateparser):
//!    `Locale._translate_numerals` (ASCII digits only, see below), `normalize_unicode` (NFKD without characters of
//!    class Mn), `Locale._simplify` (lowercase + `simplifications`, Russian: compound
//!    ordinal numbers), `Dictionary.split` (relative patterns, then known words longest first),
//!    `Dictionary.are_tokens_valid` (otherwise the language is not applicable), `Locale.translate`
//!    (relative patterns → English, dictionary, `_clear_future_words`)
//! 3. `FreshnessDateDataParser._parse_date` on the English text: only units/`ago`/`in`/numbers,
//!    pairs `<number> <unit>`, direction via `\bin\b`, `relativedelta` (years/months integral, first
//!    months with day capping, then the rest as `timedelta`).
//!
//! Deliberately not re-implemented (contract pl-docfilter, Known differences): time zone abbreviations in the text
//! (`pop_tz_offset_from_string`), digits of other scripts (`_translate_numerals`), without
//! `DATE_PARSER_LANGUAGES` only the languages from `relative_dp_data.rs` instead of all ~200 dateparser languages.

use std::collections::HashMap;
use std::sync::OnceLock;

use chrono::{Datelike, Duration, Months, NaiveDate, NaiveDateTime};
use fancy_regex::Regex;
use unicode_normalization::UnicodeNormalization;

use crate::relative_dp_data::DP_LANGS;

/// Language data of a dateparser language (generated, see module header).
pub(crate) struct DpLang {
    pub(crate) code: &'static str,
    /// `Locale._process_russian_compound_ordinals` after the simplifications
    pub(crate) russian_ordinals: bool,
    /// (pattern, replacement), already with the word-boundary wrapper from `_get_simplifications`
    pub(crate) simplifications: &'static [(&'static str, &'static str)],
    /// `_get_sorted_relative_strings_from_cache` (parentheses removed, longest first)
    pub(crate) relative_strings: &'static [&'static str],
    /// `_get_relative_translations`: (`^(?:…)$`, English replacement with `{n}`)
    pub(crate) relative_translations: &'static [(&'static str, &'static str)],
    /// `_get_sorted_words_from_cache` with value (`""` = skip word)
    pub(crate) words: &'static [(&'static str, &'static str)],
}

struct Compiled {
    simplifications: Vec<(Regex, &'static str)>,
    split_relative: Option<Regex>,
    match_relative: Option<Regex>,
    relative_translations: Vec<(Regex, &'static str)>,
    words: HashMap<&'static str, &'static str>,
}

/// Patterns that fancy-regex cannot translate (should stay empty; test `all_patterns_compile`).
fn compile(p: &str, bad: &mut Vec<String>) -> Option<Regex> {
    match Regex::new(p) {
        Ok(r) => Some(r),
        Err(e) => {
            bad.push(format!("{p}: {e}"));
            None
        }
    }
}

fn compile_lang(l: &DpLang, bad: &mut Vec<String>) -> Compiled {
    let simplifications = l.simplifications.iter().filter_map(|(p, r)| compile(p, bad).map(|re| (re, *r))).collect();
    let alts = l.relative_strings.join("|");
    // dateparser compiles with re.IGNORECASE; unnecessary here because text (after `_simplify`) and patterns are
    // already lowercase – saves a lot of pattern translation time.
    let (split_relative, match_relative) = if l.relative_strings.is_empty() {
        (None, None)
    } else {
        (
            compile(&format!(r"(?:\A|(?<=[\W_]))({alts})(?=\z|[\W_])"), bad),
            compile(&format!(r"^({alts})$"), bad),
        )
    };
    let relative_translations = l.relative_translations.iter().filter_map(|(p, r)| compile(p, bad).map(|re| (re, *r))).collect();
    Compiled { simplifications, split_relative, match_relative, relative_translations, words: l.words.iter().copied().collect() }
}

fn compiled(idx: usize) -> Option<&'static Compiled> {
    static CACHE: OnceLock<Vec<OnceLock<Compiled>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| DP_LANGS.iter().map(|_| OnceLock::new()).collect());
    let l = DP_LANGS.get(idx)?;
    Some(cache.get(idx)?.get_or_init(|| compile_lang(l, &mut Vec::new())))
}

// ---------------------------------------------------------------------------------------
// Character classes like Python's `re` (Unicode)
// ---------------------------------------------------------------------------------------

fn is_digit(c: char) -> bool {
    c.is_numeric()
}

/// `\w`
fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// `(?:\A|\W|_|\d)` before and `(?:\Z|\W|_|\d)` after a known word
fn is_split_boundary(c: Option<char>) -> bool {
    match c {
        None => true,
        Some(c) => !is_word(c) || c == '_' || is_digit(c),
    }
}

const ALWAYS_KEEP_TOKENS: [&str; 6] = ["+", ":", ".", " ", "-", "/"];

/// `Dictionary._should_capture` (keep_formatting = False)
fn should_capture(t: &str) -> bool {
    ALWAYS_KEEP_TOKENS.contains(&t) || t.chars().any(|c| is_word(c) && c != '_')
}

/// `Dictionary._split_by_numerals`: `NUMERAL_PATTERN = (\d+)`
fn split_by_numerals(s: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_digit = None;
    for c in s.chars() {
        let d = is_digit(c);
        if cur_digit.is_some_and(|x| x != d) {
            out.push(std::mem::take(&mut cur));
        }
        cur_digit = Some(d);
        cur.push(c);
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out.into_iter().filter(|t| should_capture(t)).collect()
}

// ---------------------------------------------------------------------------------------
// date.sanitize_date
// ---------------------------------------------------------------------------------------

fn re(p: &str) -> Option<Regex> {
    Regex::new(p).ok()
}

struct Sanitize {
    skip: Option<Regex>,
    russian: Option<Regex>,
    croatian: Option<Regex>,
    spaces: Option<Regex>,
    trim_spaces: Option<Regex>,
    on: Option<Regex>,
    trim_colons: Option<Regex>,
}

fn sanitize_res() -> &'static Sanitize {
    static S: OnceLock<Sanitize> = OnceLock::new();
    S.get_or_init(|| Sanitize {
        skip: re(r"\t|\n|\r|\x{bb}|,\s\x{432}\b|\x{200e}|\x{b7}|\x{200f}|\x{64e}|\x{64f}"),
        russian: re(r"(?i)([\W\d])\x{433}\."),
        croatian: re(r"(?i)(\d+)\.\s?(\d+)\.\s?(\d+)\.( u)?"),
        spaces: re(r"\s+"),
        trim_spaces: re(r"^\s+(\S.*?)\s+$"),
        on: re(r"^.*?on:\s+(.*)"),
        trim_colons: re(r"(\S.*?):*$"),
    })
}

fn sub_all(r: &Option<Regex>, s: &str, rep: &str) -> String {
    match r {
        Some(r) => r.replace_all(s, rep).into_owned(),
        None => s.to_string(),
    }
}

fn sub_first(r: &Option<Regex>, s: &str, rep: &str) -> String {
    match r {
        Some(r) => r.replace(s, rep).into_owned(),
        None => s.to_string(),
    }
}

const APOSTROPHE_LOOK_ALIKE: [char; 9] = ['\u{2019}', '\u{2bc}', '\u{2bb}', '\u{55a}', '\u{a78c}', '\u{2032}', '\u{2035}', '\u{2b9}', '\u{ff07}'];

pub(crate) fn sanitize_date(s: &str) -> String {
    let r = sanitize_res();
    let s = sub_all(&r.skip, s, " ");
    let s = sub_all(&r.russian, &s, "${1} ");
    let s = sub_all(&r.croatian, &s, "${1}.${2}.${3} ");
    // sanitize_spaces
    let s = s.replace('\u{a0}', " ");
    let s = sub_all(&r.spaces, &s, " ");
    let s = sub_first(&r.trim_spaces, &s, "${1}");
    // RE_SANITIZE_PERIOD `(?<=[^0-9\s])\.` (lookbehind on the original text)
    let mut out = String::with_capacity(s.len());
    let mut prev: Option<char> = None;
    for c in s.chars() {
        let drop = c == '.' && prev.is_some_and(|p| !p.is_ascii_digit() && !p.is_whitespace());
        if !drop {
            out.push(c);
        }
        prev = Some(c);
    }
    let s = sub_first(&r.on, &out, "${1}");
    let s = sub_first(&r.trim_colons, &s, "${1}");
    let s: String = s.chars().map(|c| if APOSTROPHE_LOOK_ALIKE.contains(&c) { '\'' } else { c }).collect();
    s.trim().to_string()
}

// ---------------------------------------------------------------------------------------
// Locale.translate
// ---------------------------------------------------------------------------------------

/// `normalize_unicode` (NFKD, characters of class Mn removed) + `_simplify`
fn simplify(l: &DpLang, c: &Compiled, s: &str) -> String {
    let norm: String = s.nfkd().filter(|ch| !unicode_normalization::char::is_combining_mark(*ch)).collect();
    let mut s = norm.to_lowercase();
    for (re, rep) in &c.simplifications {
        s = re.replace_all(&s, *rep).to_lowercase();
    }
    if l.russian_ordinals {
        s = russian_compound_ordinals(&s);
    }
    s
}

/// `_process_russian_compound_ordinals`: `\b(\d+)\s+(\d+)\b` → sum for 20/30 + 1..9
fn russian_compound_ordinals(s: &str) -> String {
    static PAIR: OnceLock<Option<Regex>> = OnceLock::new();
    let Some(r) = PAIR.get_or_init(|| re(r"\b(\d+)\s+(\d+)\b")) else { return s.to_string() };
    let mut out = String::new();
    let mut last = 0;
    for caps in r.captures_iter(s).flatten() {
        let (Some(m), Some(a), Some(b)) = (caps.get(0), caps.get(1), caps.get(2)) else { continue };
        let (Ok(x), Ok(y)) = (a.as_str().parse::<u64>(), b.as_str().parse::<u64>()) else { continue };
        let sum = x.saturating_add(y);
        out.push_str(&s[last..m.start()]);
        if (1..=31).contains(&sum) && (x == 20 || x == 30) && (1..=9).contains(&y) {
            out.push_str(&sum.to_string());
        } else {
            out.push_str(m.as_str());
        }
        last = m.end();
    }
    out.push_str(&s[last..]);
    out
}

/// Earliest match of `^(.*?(?:\A|\W|_|\d))(known)((?:\Z|\W|_|\d).*)$`: position at the start or
/// after a boundary character, there the first (= longest) word with a boundary after it.
fn find_known(l: &DpLang, s: &str) -> Option<(usize, usize)> {
    let mut prev: Option<char> = None;
    for (off, ch) in s.char_indices() {
        if off == 0 || is_split_boundary(prev) {
            let tail = &s[off..];
            for (w, _) in l.words {
                if !w.is_empty() && tail.starts_with(w) && is_split_boundary(tail[w.len()..].chars().next()) {
                    return Some((off, off + w.len()));
                }
            }
        }
        prev = Some(ch);
    }
    None
}

/// `Dictionary._split_by_known_words`
fn split_by_known_words(l: &DpLang, s: &str, out: &mut Vec<String>) {
    let push = |out: &mut Vec<String>, tok: String| {
        if ["st", "nd", "rd", "th"].contains(&tok.as_str()) && out.last().is_some_and(|p| !p.is_empty() && p.chars().all(is_digit)) {
            return;
        }
        out.push(tok);
    };
    let mut string = s;
    while !string.is_empty() {
        match find_known(l, string) {
            None => {
                if should_capture(string) {
                    for t in split_by_numerals(string) {
                        push(out, t);
                    }
                }
                break;
            }
            Some((a, b)) => {
                let (unparsed, known) = (&string[..a], &string[a..b]);
                if !unparsed.is_empty() && should_capture(unparsed) {
                    for t in split_by_numerals(unparsed) {
                        push(out, t);
                    }
                }
                if should_capture(known) {
                    push(out, known.to_string());
                }
                string = &string[b..];
            }
        }
    }
}

/// `Dictionary.split`
fn split(l: &DpLang, c: &Compiled, s: &str) -> Vec<String> {
    let mut pieces: Vec<(&str, bool)> = Vec::new();
    match &c.split_relative {
        Some(r) => {
            let mut last = 0;
            for caps in r.captures_iter(s).flatten() {
                let Some(m) = caps.get(1) else { continue };
                pieces.push((&s[last..m.start()], false));
                pieces.push((m.as_str(), true));
                last = m.end();
            }
            pieces.push((&s[last..], false));
        }
        None => pieces.push((s, false)),
    }
    let mut out = Vec::new();
    for (p, _) in pieces {
        if p.is_empty() {
            continue;
        }
        if c.match_relative.as_ref().is_some_and(|r| r.is_match(p).unwrap_or(false)) {
            out.push(p.to_string());
        } else {
            split_by_known_words(l, p, &mut out);
        }
    }
    out.retain(|t| !t.is_empty());
    out
}

/// `Dictionary.are_tokens_valid`
fn tokens_valid(c: &Compiled, tokens: &[String]) -> bool {
    if tokens.iter().all(|t| ALWAYS_KEEP_TOKENS.contains(&t.as_str())) {
        return false;
    }
    tokens.iter().all(|t| {
        (!t.is_empty() && t.chars().all(is_digit))
            || c.match_relative.as_ref().is_some_and(|r| r.is_match(t).unwrap_or(false))
            || c.words.contains_key(t.as_str())
    })
}

/// Rest of `Locale.translate`: relative patterns, dictionary, `_clear_future_words`, `_join`
fn translate(c: &Compiled, tokens: Vec<String>) -> String {
    let mut out: Vec<String> = Vec::with_capacity(tokens.len());
    for t in tokens {
        let w = t.to_lowercase();
        let mut done = None;
        for (re, rep) in &c.relative_translations {
            if let Ok(Some(caps)) = re.captures(&w) {
                let n = (1..caps.len()).find_map(|i| caps.get(i)).map(|m| m.as_str()).unwrap_or("");
                done = Some(rep.replace("{n}", n));
                break;
            }
        }
        out.push(match done {
            Some(x) => x,
            None => match c.words.get(w.as_str()) {
                Some(v) => (*v).to_string(),
                None => w,
            },
        });
    }
    // _clear_future_words: first "in" removed if no unit word (singular) stands as a word of its own
    const FRESHNESS: [&str; 7] = ["day", "week", "month", "year", "hour", "minute", "second"];
    if !out.iter().any(|t| FRESHNESS.contains(&t.as_str()))
        && let Some(i) = out.iter().position(|t| t == "in")
    {
        out[i].clear();
    }
    out.into_iter().filter(|t| !t.is_empty()).collect::<Vec<_>>().join(" ")
}

// ---------------------------------------------------------------------------------------
// FreshnessDateDataParser
// ---------------------------------------------------------------------------------------

fn freshness_res() -> &'static (Option<Regex>, Option<Regex>, Option<Regex>) {
    static R: OnceLock<(Option<Regex>, Option<Regex>, Option<Regex>)> = OnceLock::new();
    R.get_or_init(|| {
        (
            re(r"(?i)([+-]?\s*\d++[.,]?\d*+)\s*(decade|year|month|week|day|hour|minute|second)\b"),
            re(r"^(?:decade|year|month|week|day|hour|minute|second|ago|in|\d+|:|[ap]m)"),
            re(r"\bin\b"),
        )
    })
}

/// Python `round()` to microseconds (half values to the even number, like `timedelta`)
fn round_half_even(x: f64) -> f64 {
    let r = x.round();
    if (x - x.trunc()).abs() == 0.5 { 2.0 * (x / 2.0).round() } else { r }
}

fn freshness(s: &str, now: NaiveDateTime) -> Option<NaiveDate> {
    let (pattern, unit_word, in_word) = freshness_res();
    let (pattern, unit_word, in_word) = (pattern.as_ref()?, unit_word.as_ref()?, in_word.as_ref()?);
    // strip_braces
    let s: String = s.chars().filter(|c| !"{}()<>[]".contains(*c)).collect();
    // _are_all_words_units
    let collapsed = s.split_whitespace().collect::<Vec<_>>().join(" ");
    if !collapsed.split(|c: char| !is_word(c)).filter(|w| !w.is_empty()).all(|w| unit_word.is_match(w).unwrap_or(false)) {
        return None;
    }
    // get_kwargs
    let mut kwargs: Vec<(String, f64, bool)> = Vec::new();
    for caps in pattern.captures_iter(&s).flatten() {
        let (Some(num), Some(unit)) = (caps.get(1), caps.get(2)) else { continue };
        let num = num.as_str();
        let explicit = num.starts_with('+') || num.starts_with('-');
        let v: f64 = num.replace(',', ".").replace(' ', "").parse().ok()?;
        let key = unit.as_str().to_lowercase();
        match kwargs.iter_mut().find(|(k, _, _)| *k == key) {
            Some(e) => {
                e.1 = v;
                e.2 = explicit;
            }
            None => kwargs.push((key, v, explicit)),
        }
    }
    if kwargs.is_empty() {
        return None;
    }
    let forward = in_word.is_match(&s).unwrap_or(false);
    let get = |k: &str| {
        kwargs.iter().find(|(u, _, _)| u == k).map(|(_, v, e)| if *e || forward { *v } else { -*v }).unwrap_or(0.0)
    };
    // relativedelta: decades → years; years/months must be integral
    let years = get("year") + 10.0 * get("decade");
    let months = get("month");
    if years.fract() != 0.0 || months.fract() != 0.0 || !years.is_finite() || !months.is_finite() {
        return None;
    }
    let total_months = years.mul_add(12.0, months);
    if total_months.abs() > 1.2e6 {
        return None;
    }
    let total_months = total_months as i64;
    let base = if total_months >= 0 {
        now.checked_add_months(Months::new(u32::try_from(total_months).ok()?))?
    } else {
        now.checked_sub_months(Months::new(u32::try_from(-total_months).ok()?))?
    };
    if !(1..=9999).contains(&base.year()) {
        return None;
    }
    let secs = get("week") * 7.0 * 86400.0 + get("day") * 86400.0 + get("hour") * 3600.0 + get("minute") * 60.0 + get("second");
    let micros = round_half_even(secs * 1e6);
    // timedelta: at most 999999999 days
    if !micros.is_finite() || micros.abs() >= 999_999_999.0 * 86_400.0 * 1e6 {
        return None;
    }
    let dt = base.checked_add_signed(Duration::microseconds(micros as i64))?;
    if !(1..=9999).contains(&dt.year()) {
        return None;
    }
    Some(dt.date())
}

fn parse_in_lang(idx: usize, s: &str, now: NaiveDateTime) -> Option<NaiveDate> {
    let l = DP_LANGS.get(idx)?;
    let c = compiled(idx)?;
    let simplified = simplify(l, c, s);
    let tokens = split(l, c, &simplified);
    if !tokens_valid(c, &tokens) {
        return None;
    }
    freshness(&translate(c, tokens), now)
}

/// `dateparser.parse(value, locales=…, settings={"PARSERS": ["relative-time"], "RELATIVE_BASE": now})`
/// – first applicable language (in dateparser order) with a result.
pub(crate) fn parse(value: &str, now: NaiveDateTime, enabled: impl Fn(&str) -> bool) -> Option<NaiveDate> {
    let s = sanitize_date(value);
    if s.is_empty() {
        return None;
    }
    (0..DP_LANGS.len()).filter(|&i| enabled(DP_LANGS[i].code)).find_map(|i| parse_in_lang(i, &s, now))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_patterns_compile() {
        let mut bad = Vec::new();
        for l in DP_LANGS {
            compile_lang(l, &mut bad);
        }
        assert!(bad.is_empty(), "{}", bad.join("\n"));
        assert!(freshness_res().0.is_some() && freshness_res().1.is_some() && freshness_res().2.is_some());
    }

    #[test]
    fn sanitize_like_dateparser() {
        assert_eq!(sanitize_date("  3\u{a0}days   ago. "), "3 days ago");
        assert_eq!(sanitize_date("vor 2 Tagen:"), "vor 2 Tagen");
        assert_eq!(sanitize_date("l\u{2019}altro ieri"), "l'altro ieri");
    }
}
